const $=id=>document.getElementById(id);
const fmtInt=n=>Number(n||0).toLocaleString('en-US',{maximumFractionDigits:0});
const fmt1=n=>Number(n||0).toLocaleString('en-US',{maximumFractionDigits:1});
const pct=n=>(Number(n||0)*100).toFixed(1)+'%';
const money=n=>'$'+fmtInt(n);
let sortKey='_objective', sortDir=-1, selected=null, compare=[];

function marketStates(r){
 if(r.State) return [r.State];
 const m=String(r.Market||'').match(/\s([A-Z]{2}(?:-[A-Z]{2})*)$/);
 return m ? m[1].split('-') : [];
}
const states=[...new Set([...DB.counties,...DB.metros].flatMap(marketStates).filter(Boolean))].sort();
states.forEach(s=>{const o=document.createElement('option');o.value=s;o.textContent=s;$('state').appendChild(o)});

function objectiveLabel(){
 return $('objective').options[$('objective').selectedIndex].text;
}
function scoreVal(r){
 const k=$('objective').value;
 return Number(r[k]||0);
}
function filtered(){
 const data=DB[$('geo').value];
 const q=$('marketSearchBox').textContent.trim().toLowerCase();
 const st=$('state').value;
 let arr=data.filter(r=>(!q||String(r.Market).toLowerCase().includes(q)) && (!st||marketStates(r).includes(st)));
 arr=arr.map(r=>Object.assign({},r,{_objective:scoreVal(r)}));
 arr.sort((a,b)=>{
   let av=sortKey==='_rank'?0:a[sortKey], bv=sortKey==='_rank'?0:b[sortKey];
   if(sortKey==='_rank') return 0;
   if(typeof av==='string') return sortDir*String(av).localeCompare(String(bv));
   return sortDir*(Number(av||0)-Number(bv||0));
 });
 if(sortKey==='_rank') arr.sort((a,b)=>b._objective-a._objective);
 arr.forEach((r,i)=>r._rank=i+1);
 return arr;
}

function csvEscape(v){
 const s=String(v??'');
 return /[",\n]/.test(s) ? '"'+s.replace(/"/g,'""')+'"' : s;
}
function exportCsv(){
 const rows=filtered();
 const cols=['_rank','Market','State','Population','Households','Renter_HH','Renter_Share','Vacancy_Rate','Median_Rent_Wtd','Median_HHI_Wtd','Property_Score','Marketing_Need','Portfolio_Snapshot','Risk','Overall_Opportunity','Acquisition_Screen','Disposition_Screen','Strategic_Snapshot'];
 const header=cols.map(c=>c==='_rank'?'Current Rank':c).join(',');
 const body=rows.map(r=>cols.map(c=>csvEscape(r[c])).join(',')).join('\n');
 const blob=new Blob([header+'\n'+body],{type:'text/csv;charset=utf-8'});
 const a=document.createElement('a');
 a.href=URL.createObjectURL(blob);
 a.download='apartment-market-ranking.csv';
 document.body.appendChild(a); a.click(); a.remove();
 setTimeout(()=>URL.revokeObjectURL(a.href),500);
}
function renderCompare(){
 const panel=$('comparePanel'), table=$('compareTable');
 if(!compare.length){ panel.style.display='none'; table.innerHTML=''; return; }
 panel.style.display='block';
 const metrics=[
  ['Population',r=>fmtInt(r.Population)],
  ['Households',r=>fmtInt(r.Households)],
  ['Renter households',r=>fmtInt(r.Renter_HH)],
  ['Renter share',r=>pct(r.Renter_Share)],
  ['Vacancy rate',r=>pct(r.Vacancy_Rate)],
  ['Median monthly rent',r=>money(r.Median_Rent_Wtd)],
  ['Median HHI',r=>money(r.Median_HHI_Wtd)],
  ['Property strength',r=>fmt1(r.Property_Score)],
  ['Marketing opportunity',r=>fmt1(r.Marketing_Need)],
  ['Market strength',r=>fmt1(r.Portfolio_Snapshot)],
  ['Market risk',r=>fmt1(r.Risk)],
  ['Overall market opportunity',r=>fmt1(r.Overall_Opportunity)],
  ['Renter market depth',r=>fmt1(r.Demand_Depth_Proxy)],['New-supply pressure',r=>fmt1(r.Supply_Pressure_Proxy)],['Expansion opportunity',r=>fmt1(r.Acquisition_Enhanced)],['Attention priority',r=>fmt1(r.Disposition_Enhanced)]
 ];
 table.innerHTML='<thead><tr><th>Metric</th>'+compare.map(r=>'<th>'+r.Market+'</th>').join('')+'</tr></thead><tbody>'+
 metrics.map(m=>'<tr><td><strong>'+m[0]+'</strong></td>'+compare.map(r=>'<td class="num">'+m[1](r)+'</td>').join('')+'</tr>').join('')+'</tbody>';
}
function addSelectedToCompare(){
 if(!selected) return;
 if(compare.some(r=>r.Kind===selected.Kind && r.Market===selected.Market)) return;
 if(compare.length>=4) compare.shift();
 compare.push(selected);
 renderCompare();
}

function render(){
 let all=filtered();
 const show=all.slice(0,+$('topn').value);
 $('tbody').innerHTML=show.map(r=>`<tr data-id="${encodeURIComponent(r.Market)}" class="${selected&&selected.Market===r.Market?'selected':''}">
 <td class="rank">${r._rank}</td><td><strong>${r.Market}</strong></td><td class="num">${fmtInt(r.Population)}</td>
 <td class="num">${fmtInt(r.Renter_HH)}</td><td class="num">${pct(r.Vacancy_Rate)}</td><td class="num">${money(r.Median_Rent_Wtd)}</td>
 <td class="num">${fmt1(r.Property_Score)}</td><td class="num">${fmt1(r.Portfolio_Snapshot)}</td><td class="num">${fmt1(r.Risk)}</td>
 <td class="num"><strong>${fmt1(r._objective)}</strong></td><td><span class="badge">${r.Strategic_Snapshot||''}</span></td></tr>`).join('');
 document.querySelectorAll('#tbody tr').forEach(tr=>tr.addEventListener('click',()=>{
   const market=decodeURIComponent(tr.dataset.id); selected=all.find(r=>r.Market===market); renderDetail(); render();
 }));
 const renters=all.reduce((s,r)=>s+Number(r.Renter_HH||0),0);
 const avg=(key)=>all.length?all.reduce((s,r)=>s+Number(r[key]||0),0)/all.length:0;
 $('kMarkets').textContent=fmtInt(all.length); $('kRenters').textContent=fmtInt(renters);
 $('kVacancy').textContent=pct(avg('Vacancy_Rate')); $('kRent').textContent=money(avg('Median_Rent_Wtd'));
 $('kScore').textContent=fmt1(all.length?all.reduce((s,r)=>s+r._objective,0)/all.length:0);
}
function marketExplanation(r){
 const positives=[], cautions=[];
 if(Number(r.Demand_Depth_Proxy||0)>=65) positives.push('a comparatively deep renter market');
 if(Number(r.Property_Score||0)>=65) positives.push('favorable property-market fundamentals');
 if(Number(r.Portfolio_Snapshot||0)>=65) positives.push('solid overall market strength');
 if(Number(r.Marketing_Need||0)>=65) positives.push('meaningful marketing opportunity');
 if(Number(r.Vacancy_Rate||0)>=0.12) cautions.push('vacancy is relatively elevated');
 if(Number(r.Supply_Pressure_Proxy||0)>=65) cautions.push('new-supply/vacancy pressure is higher');
 if(Number(r.Risk||0)>=65) cautions.push('the market-risk score is elevated');
 const pos=positives.length ? 'The score is supported by '+positives.slice(0,2).join(' and ')+'.' : 'The market shows a mixed set of current-condition indicators.';
 const caution=cautions.length ? ' Keep in mind that '+cautions.slice(0,2).join(' and ')+'.' : ' No major caution flag stands out in the current screening metrics.';
 return pos+caution+' Use these results to prioritize follow-up analysis rather than as a stand-alone investment recommendation.';
}

function renderDetail(){
 if(!selected)return;
 const r=selected, obj=$('objective').value;
 $('detail').innerHTML=`<h2>${r.Market}</h2><div class="sub">${objectiveLabel()} · current source rank ${fmtInt(r.Rank)}</div><div class="legend" style="margin-top:0;padding-top:0;border-top:0;margin-bottom:14px"><strong>What the data suggests:</strong> ${marketExplanation(r)}</div>
 <div class="scorebox">
 <div class="score"><b>${fmt1(r[obj])}</b><span>${objectiveLabel()}</span></div>
 <div class="score"><b>${fmt1(r.Overall_Opportunity)}</b><span>Overall market opportunity</span></div>
 <div class="score"><b>${fmt1(r.Acquisition_Enhanced)}</b><span>Expansion opportunity</span></div>
 <div class="score"><b>${fmt1(r.Disposition_Enhanced)}</b><span>Attention priority</span></div>
 </div>
 ${[
 ['Population',fmtInt(r.Population)],['Households',fmtInt(r.Households)],['Renter households',fmtInt(r.Renter_HH)],
 ['Renter share',pct(r.Renter_Share)],['Vacancy rate',pct(r.Vacancy_Rate)],['Median monthly rent',money(r.Median_Rent_Wtd)],
 ['Median household income',money(r.Median_HHI_Wtd)],['Rent-to-income ratio',pct(r.Rent_to_Income_Wtd)],['Property strength',fmt1(r.Property_Score)],['Marketing opportunity',fmt1(r.Marketing_Need)],
 ['Market strength',fmt1(r.Portfolio_Snapshot)],['Market risk',fmt1(r.Risk)],
 ['Renter market depth',fmt1(r.Demand_Depth_Proxy)],['New-supply pressure',fmt1(r.Supply_Pressure_Proxy)],['Recent construction share',r.Recent_Build_Share==null?'—':pct(r.Recent_Build_Share)],['Data coverage',fmt1(r.Data_Quality)]
 ].map(x=>`<div class="metric"><span>${x[0]}</span><strong>${x[1]}</strong></div>`).join('')}
 <div class="legend"><strong>Market outlook:</strong> ${r.Strategic_Snapshot||'—'}<br><br>
 <strong>How the scores work:</strong> Expansion Opportunity emphasizes property strength, market strength and renter-market depth while accounting for supply pressure and risk. Attention Priority emphasizes higher risk, supply pressure and marketing opportunity. Renter Market Depth reflects renter concentration, age 21–34 concentration and renter-household scale. New-Supply Pressure reflects recent construction and vacancy.</div>`;
 const btn=$('addCompare'); if(btn) btn.addEventListener('click',addSelectedToCompare);
}
['geo','objective','state','topn'].forEach(id=>$(id).addEventListener('change',()=>{selected=null;render()}));
$('marketSearchBox').addEventListener('input',()=>{selected=null;render()});
$('marketSearchBox').addEventListener('keydown',e=>{if(e.key==='Enter')e.preventDefault();});
$('exportCsv').addEventListener('click',exportCsv);
$('clearCompare').addEventListener('click',()=>{compare=[];renderCompare();});
document.querySelectorAll('th[data-key]').forEach(th=>th.addEventListener('click',()=>{
 const k=th.dataset.key; if(sortKey===k)sortDir*=-1; else{sortKey=k;sortDir=-1} render();
}));

function setMode(mode){
 const national=mode==='national';
 $('nationalView').classList.toggle('hidden',!national);
 $('radiusView').classList.toggle('hidden',national);
 $('modeNational').classList.toggle('active',national);
 $('modeRadius').classList.toggle('active',!national);
}
$('modeNational').addEventListener('click',()=>setMode('national'));
$('modeRadius').addEventListener('click',()=>setMode('radius'));

function haversineMiles(lat1,lon1,lat2,lon2){
 const R=3958.7613, toRad=x=>x*Math.PI/180;
 const dLat=toRad(lat2-lat1), dLon=toRad(lon2-lon1);
 const a=Math.sin(dLat/2)**2+Math.cos(toRad(lat1))*Math.cos(toRad(lat2))*Math.sin(dLon/2)**2;
 return 2*R*Math.asin(Math.sqrt(a));
}
let radiusRows=[];
function percentileScale(rows,key){
 const vals=rows.map(r=>Math.max(0,Number(r[key]||0))).sort((a,b)=>a-b);
 return function(v){
   v=Math.max(0,Number(v||0));
   let lo=0,hi=vals.length;
   while(lo<hi){const mid=(lo+hi)>>1;if(vals[mid]<=v)lo=mid+1;else hi=mid;}
   return vals.length<=1?100:100*(lo-1)/(vals.length-1);
 };
}
function objectiveWeights(objective){
 if(objective==='leaseup') return {property:.30,scale:.20,need:.35,distance:.15,label:'Lease-up / vacancy pressure'};
 if(objective==='audience') return {property:.25,scale:.45,need:.10,distance:.20,label:'Maximize renter reach'};
 return {property:.40,scale:.25,need:.20,distance:.15,label:'Balanced leasing'};
}
function runRadius(){
 const zip=String($('centerZip').value||'').trim().padStart(5,'0');
 const center=ZIPDB.find(r=>r.ZIP===zip);
 if(!center){
   $('radiusMessage').innerHTML='<strong>ZIP not found.</strong> Enter a valid five-digit ZIP from the national ZIP database.';
   $('radiusKpis').classList.add('hidden'); $('radiusResults').classList.add('hidden'); $('radiusExportWrap').classList.add('hidden');
   return;
 }
 const miles=Number($('radiusMiles').value||10);
 const budget=Math.max(0,Number($('radiusBudget').value||0));
 const objective=$('radiusObjective').value||'balanced';
 const ow=objectiveWeights(objective);
 let rows=[];
 for(const r of ZIPDB){
   const d=haversineMiles(Number(center.Latitude),Number(center.Longitude),Number(r.Latitude),Number(r.Longitude));
   if(d<=miles) rows.push(Object.assign({},r,{Distance:d}));
 }
 const renterPct=percentileScale(rows,'Renter_HH');
 for(const r of rows){
   const property=Math.max(0,Math.min(100,Number(r.Property_Advertising_Score||0)));
   const need=Math.max(0,Math.min(100,Number(r.Marketing_Need_Score||0)));
   const scale=renterPct(r.Renter_HH);
   const distance=Math.max(0,100*(1-r.Distance/Math.max(miles,0.01)));
   r._renterScale=scale; r._distanceScore=distance;
   r._marketingScore=ow.property*property+ow.scale*scale+ow.need*need+ow.distance*distance;
   const distanceDecay=Math.exp(-1.6*r.Distance/Math.max(miles,0.01));
   r._distanceDecay=distanceDecay;
   r._weight=Math.pow(Math.max(r._marketingScore,1),1.35)*distanceDecay;
 }
 rows.sort((a,b)=>{
   if(b._marketingScore!==a._marketingScore) return b._marketingScore-a._marketingScore;
   return Number(b.Renter_HH||0)-Number(a.Renter_HH||0);
 });
 const totalWeight=rows.reduce((s,r)=>s+r._weight,0)||1;
 rows.forEach((r,i)=>{r._rank=i+1;r._share=r._weight/totalWeight;r._dollars=budget*r._share});
 radiusRows=rows;

 $('radiusMessage').innerHTML=`Centered on <strong>${center.ZIP} ${center.City||''}, ${center.State||''}</strong>. Showing every ZIP centroid within <strong>${miles} miles</strong>. Objective: <strong>${ow.label}</strong>.`;
 $('radiusKpis').classList.remove('hidden'); $('radiusResults').classList.remove('hidden'); $('radiusExportWrap').classList.remove('hidden');
 $('rzCount').textContent=fmtInt(rows.length);
 $('rzRenters').textContent=fmtInt(rows.reduce((s,r)=>s+Number(r.Renter_HH||0),0));
 $('rzMF').textContent=fmtInt(rows.reduce((s,r)=>s+Number(r.Multifamily_20plus_Units||0),0));
 $('rzScore').textContent=fmt1(rows.length?rows.reduce((s,r)=>s+Number(r.Property_Advertising_Score||0),0)/rows.length:0);
 $('rzBudget').textContent=budget?('$'+fmtInt(budget)):'Not entered';
 $('radiusBody').innerHTML=rows.map(r=>`<tr>
 <td class="rank">${r._rank}</td><td><strong>${r.ZIP}</strong></td><td>${r.City||''}, ${r.State||''}</td>
 <td class="num">${r.Distance.toFixed(1)} mi</td><td class="num">${fmtInt(r.Renter_HH)}</td><td class="num">${pct(r.Renter_Share)}</td>
 <td class="num">${fmtInt(r.Multifamily_20plus_Units)}</td><td class="num">${r.Median_Rent?money(r.Median_Rent):'—'}</td>
 <td class="num">${fmt1(r.Property_Advertising_Score)}</td><td class="num">${fmt1(r.Marketing_Need_Score)}</td>
 <td class="num"><strong>${fmt1(r._marketingScore)}</strong></td><td class="num">${fmt1(r.Overall_Adtaxi_Opportunity)}</td><td class="num">${(r._share*100).toFixed(1)}%</td>
 <td class="num">${budget?money(Math.round(r._dollars)):'—'}</td></tr>`).join('');
}
$('runRadius').addEventListener('click',runRadius);
$('centerZip').addEventListener('keydown',e=>{if(e.key==='Enter')runRadius();});

function exportRadiusCsv(){
 if(!radiusRows.length)return;
 const budget=Math.max(0,Number($('radiusBudget').value||0));
 const cols=[
  ['Rank',r=>r._rank],['ZIP',r=>r.ZIP],['City',r=>r.City],['State',r=>r.State],['County',r=>r.County],
  ['Distance_Miles',r=>r.Distance.toFixed(2)],['Population',r=>r.Population],['Households',r=>r.Households],
  ['Renter_HH',r=>r.Renter_HH],['Renter_Share',r=>r.Renter_Share],['Multifamily_20plus_Units',r=>r.Multifamily_20plus_Units],
  ['Median_Rent',r=>r.Median_Rent],['Advertising_Opportunity',r=>r.Property_Advertising_Score],
  ['Marketing_Opportunity',r=>r.Marketing_Need_Score],['ZIP_Marketing_Score',r=>r._marketingScore],['Renter_Scale_Percentile',r=>r._renterScale],['Distance_Score',r=>r._distanceScore],['Distance_Decay',r=>r._distanceDecay],['Overall_Adtaxi_Opportunity',r=>r.Overall_Adtaxi_Opportunity],
  ['Budget_Share',r=>r._share],['Suggested_Dollars',r=>budget?r._dollars:'']
 ];
 const lines=[cols.map(c=>c[0]).join(',')];
 radiusRows.forEach(r=>lines.push(cols.map(c=>csvEscape(c[1](r))).join(',')));
 const blob=new Blob([lines.join('\n')],{type:'text/csv;charset=utf-8'});
 const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download='apartment-property-radius-ranking.csv';
 document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(a.href),500);
}
$('exportRadius').addEventListener('click',exportRadiusCsv);

render();
